1	package cli
2	
3	import (
4		"bufio"
5		"context"
6		"errors"
7		"fmt"
8		"io"
9		"net/url"
10		"os"
11		"os/exec"
12		"runtime"
13		"time"
14	
15		"github.com/atotto/clipboard"
16		"github.com/entireio/cli/cmd/entire/cli/auth"
17		"github.com/entireio/cli/cmd/entire/cli/interactive"
18		"github.com/spf13/cobra"
19	)
20	
21	const fallbackDeviceAuthPollInterval = time.Second
22	const defaultSlowDownBackoff = 5 * time.Second
23	const maxPollInterval = 30 * time.Second
24	const maxExpiresIn = 15 * time.Minute
25	const maxTransientErrors = 5
26	
27	// browserOpenFunc is the signature for opening a URL in the user's browser.
28	type browserOpenFunc func(ctx context.Context, url string) error
29	
30	// clipboardWriteFunc is the signature for copying text to the user's clipboard.
31	type clipboardWriteFunc func(text string) error
32	
33	// deviceAuthClient abstracts the auth client so runLogin and waitForApproval can be unit-tested.
34	type deviceAuthClient interface {
35		StartDeviceAuth(ctx context.Context) (*auth.DeviceAuthStart, error)
36		PollDeviceAuth(ctx context.Context, deviceCode string) (*auth.DeviceAuthPoll, error)
37		BaseURL() string
38	}
39	
40	func newLoginCmd() *cobra.Command {
41		var insecureHTTPAuth bool
42		cmd := &cobra.Command{
43			Use:   "login",
44			Short: "Log in to Entire",
45			RunE: func(cmd *cobra.Command, _ []string) error {
46				if err := requireSecureBaseURL(insecureHTTPAuth); err != nil {
47					return err
48				}
49				return runLogin(cmd.Context(), cmd.OutOrStdout(), cmd.ErrOrStderr(), auth.NewClient(nil), openBrowser, copyToClipboard)
50			},
51		}
52		addInsecureHTTPAuthFlag(cmd, &insecureHTTPAuth)
53		return cmd
54	}
55	
56	func runLogin(ctx context.Context, outW, errW io.Writer, client deviceAuthClient, openURL browserOpenFunc, writeClipboard clipboardWriteFunc) error {
57		start, err := client.StartDeviceAuth(ctx)
58		if err != nil {
59			return fmt.Errorf("start login: %w", err)
60		}
61	
62		fmt.Fprintf(outW, "Device code: %s\n", start.UserCode)
63	
64		approvalURL := start.VerificationURI
65	
66		if interactive.CanPromptInteractively() {
67			fmt.Fprintf(outW, "Press Enter to copy the code to your clipboard, open %s in your browser, and enter the generated device code...", approvalURL)
68	
69			// Read from /dev/tty so we get a real keypress and don't consume piped stdin.
70			if err := waitForEnter(ctx); err != nil {
71				return fmt.Errorf("wait for input: %w", err)
72			}
73	
74			fmt.Fprintln(outW)
75			if copied := copyDeviceCodeToClipboard(errW, start.UserCode, writeClipboard); copied {
76				fmt.Fprintln(outW, "Device code copied to clipboard.")
77			}
78	
79			if err := openURL(ctx, approvalURL); err != nil {
80				fmt.Fprintf(errW, "Warning: failed to open browser: %v\n", err)
81				fmt.Fprintf(outW, "Open the approval URL in your browser to continue and enter the generated device code: %s\n", approvalURL)
82			}
83		} else {
84			fmt.Fprintf(outW, "Approval URL: %s\n", approvalURL)
85		}
86	
87		fmt.Fprintln(outW, "Waiting for approval...")
88	
89		token, err := waitForApproval(ctx, client, start.DeviceCode, start.ExpiresIn, time.Duration(start.Interval)*time.Second, defaultSlowDownBackoff)
90		if err != nil {
91			return fmt.Errorf("complete login: %w", err)
92		}
93	
94		store := auth.NewStore()
95	
96		if err := store.SaveToken(client.BaseURL(), token); err != nil {
97			return fmt.Errorf("save auth token: %w", err)
98		}
99	
100		fmt.Fprintln(outW, "Login complete.")
101		return nil
102	}
103	
104	func copyDeviceCodeToClipboard(errW io.Writer, userCode string, writeClipboard clipboardWriteFunc) bool {
105		if writeClipboard == nil {
106			return false
107		}
108		if err := writeClipboard(userCode); err != nil {
109			fmt.Fprintf(errW, "Warning: failed to copy device code to clipboard: %v\n", err)
110			return false
111		}
112		return true
113	}
114	
115	func copyToClipboard(text string) error {
116		if err := clipboard.WriteAll(text); err != nil {
117			return fmt.Errorf("write clipboard: %w", err)
118		}
119		return nil
120	}
121	
122	func waitForApproval(ctx context.Context, poller deviceAuthClient, deviceCode string, expiresIn int, interval, slowDownBackoff time.Duration) (string, error) {
123		expiry := time.Duration(expiresIn) * time.Second
124		if expiry <= 0 || expiry > maxExpiresIn {
125			expiry = maxExpiresIn
126		}
127		deadline := time.Now().Add(expiry)
128		pollInterval := interval
129		if pollInterval <= 0 {
130			pollInterval = fallbackDeviceAuthPollInterval
131		}
132	
133		consecutiveErrors := 0
134	
135		for {
136			if time.Now().After(deadline) {
137				return "", errors.New("device authorization expired")
138			}
139	
140			result, err := poller.PollDeviceAuth(ctx, deviceCode)
141			if err != nil {
142				consecutiveErrors++
143				if consecutiveErrors >= maxTransientErrors {
144					return "", fmt.Errorf("poll approval status (after %d consecutive failures): %w", consecutiveErrors, err)
145				}
146				// Transient error — wait and retry.
147				select {
148				case <-ctx.Done():
