98	func runAuthStatus(ctx context.Context, w io.Writer, store tokenStore, list authTokenLister, baseURL string) error {
99		token, err := store.GetToken(baseURL)
100		if err != nil {
101			return fmt.Errorf("read keychain: %w", err)
102		}
103		if token == "" {
104			fmt.Fprintf(w, "Not logged in to %s\n", baseURL)
105			fmt.Fprintln(w, "Run 'entire login' to authenticate.")
106			return nil
107		}
108	
109		tokens, err := list(ctx, token)
110		if err != nil {
111			if api.IsHTTPErrorStatus(err, http.StatusUnauthorized) {
112				fmt.Fprintf(w, "Token in keychain for %s is no longer valid.\n", baseURL)
113				fmt.Fprintln(w, "Run 'entire login' to re-authenticate.")
114				return nil
115			}
116			return fmt.Errorf("validate token: %w", err)
117		}
118	
119		fmt.Fprintf(w, "Logged in to %s\n", baseURL)
120		fmt.Fprintln(w, "  Token: stored in OS keychain")
121		fmt.Fprintf(w, "  Active tokens on this account: %d\n", len(tokens))
122		return nil
123	}
