125	// --- list -------------------------------------------------------------------
126	
127	func newAuthListCmd() *cobra.Command {
128		var jsonOut bool
129		var insecureHTTPAuth bool
130		cmd := &cobra.Command{
131			Use:   "list",
132			Short: "List active API tokens for the authenticated user",
133			RunE: func(cmd *cobra.Command, _ []string) error {
134				if err := requireSecureBaseURL(insecureHTTPAuth); err != nil {
135					return err
136				}
137				return runAuthList(cmd.Context(), cmd.OutOrStdout(),
138					auth.NewStore(), defaultListTokens, api.BaseURL(), jsonOut)
139			},
140		}
141		cmd.Flags().BoolVar(&jsonOut, "json", false, "Print tokens as JSON")
142		addInsecureHTTPAuthFlag(cmd, &insecureHTTPAuth)
143		return cmd
144	}
145	
146	func runAuthList(ctx context.Context, w io.Writer, store tokenStore, list authTokenLister, baseURL string, jsonOut bool) error {
147		token, err := store.GetToken(baseURL)
148		if err != nil {
149			return fmt.Errorf("read keychain: %w", err)
150		}
151		if token == "" {
152			return fmt.Errorf("not logged in to %s; run 'entire login' first", baseURL)
153		}
154	
155		tokens, err := list(ctx, token)
156		if err != nil {
157			return err
158		}
159	
160		if jsonOut {
161			enc := json.NewEncoder(w)
162			enc.SetIndent("", "  ")
163			if err := enc.Encode(tokens); err != nil {
164				return fmt.Errorf("encode JSON: %w", err)
165			}
166			return nil
167		}
168	
169		if len(tokens) == 0 {
170			fmt.Fprintln(w, "No active tokens.")
171			return nil
172		}
173	
174		// Deterministic order: most recently used first, then most recently
175		// created, then by id as a final tie-breaker so the output is fully
176		// specified regardless of the server's response order.
177		sort.Slice(tokens, func(i, j int) bool {
178			li := lastUsedSortKey(tokens[i])
179			lj := lastUsedSortKey(tokens[j])
180			if li != lj {
181				return li > lj
182			}
183			if tokens[i].CreatedAt != tokens[j].CreatedAt {
184				return tokens[i].CreatedAt > tokens[j].CreatedAt
185			}
186			return tokens[i].ID < tokens[j].ID
187		})
188	
189		sty := newAuthListStyles(w)
190		renderAuthListTable(w, sty, tokens, time.Now())
191		return nil
192	}
193	
194	// authListStyles holds the lipgloss styles for `entire auth list`. Mirrors the
195	// approach in activity_render.go: keep style construction tied to color
196	// detection, and render plain text when color is disabled.
197	type authListStyles struct {
198		colorEnabled bool
199	
200		header  lipgloss.Style // bold + dim, used for column headers
201		id      lipgloss.Style // yellow accent
202		name    lipgloss.Style // bold
203		value   lipgloss.Style // default fg for scope/dates (no color)
204		dim     lipgloss.Style // "never", "-"
205		warning lipgloss.Style // expires-soon
206		expired lipgloss.Style // already expired
207	}
208	
209	func newAuthListStyles(w io.Writer) authListStyles {
210		useColor := shouldUseColor(w)
211		s := authListStyles{colorEnabled: useColor}
212		if !useColor {
213			return s
214		}
215		s.header = lipgloss.NewStyle().Foreground(lipgloss.Color("8")).Bold(true)
216		s.id = lipgloss.NewStyle().Foreground(lipgloss.Color("3")) // yellow
217		s.name = lipgloss.NewStyle().Bold(true)
218		s.value = lipgloss.NewStyle() // default fg
219		s.dim = lipgloss.NewStyle().Faint(true)
220		s.warning = lipgloss.NewStyle().Foreground(lipgloss.Color("3")) // yellow
221		s.expired = lipgloss.NewStyle().Foreground(lipgloss.Color("1")) // red
222		return s
223	}
224	
225	func (s authListStyles) render(style lipgloss.Style, text string) string {
226		if !s.colorEnabled {
227			return text
228		}
229		return style.Render(text)
230	}
231	
232	// renderAuthListTable prints a styled, column-aligned table of tokens. Column
233	// padding is computed via lipgloss.Width — it strips ANSI escapes, so a styled
234	// cell's visible width matches its plain text. tabwriter can't be used here
235	// once cells contain ANSI codes.
236	func renderAuthListTable(w io.Writer, sty authListStyles, tokens []api.Token, now time.Time) {
237		headerCells := []string{"ID", "NAME", "SCOPE", "CREATED", "LAST USED", "EXPIRES"}
238		header := make([]string, len(headerCells))
239		for i, h := range headerCells {
240			header[i] = sty.render(sty.header, h)
241		}
242	
243		rows := make([][]string, 0, len(tokens))
244		for _, t := range tokens {
245			rows = append(rows, []string{
246				sty.render(sty.id, t.ID),
247				styleName(sty, t.Name),
248				sty.render(sty.value, fallback(t.Scope, placeholderDash)),
249				sty.render(sty.value, formatAuthDate(t.CreatedAt)),
250				styleLastUsed(sty, t.LastUsedAt, now),
251				styleExpires(sty, t.ExpiresAt, now),
252			})
253		}
254	
255		widths := make([]int, len(headerCells))
256		for i, h := range header {
257			widths[i] = lipgloss.Width(h)
258		}
259		for _, row := range rows {
260			for i, c := range row {
261				if cw := lipgloss.Width(c); cw > widths[i] {
262					widths[i] = cw
263				}
264			}
265		}
266	
267		writeRow(w, header, widths)
268		for _, row := range rows {
269			writeRow(w, row, widths)
270		}
271	}
272	
273	func writeRow(w io.Writer, cells []string, widths []int) {
274		for i, c := range cells {
275			fmt.Fprint(w, c)
276			if i < len(cells)-1 {
277				fmt.Fprint(w, strings.Repeat(" ", widths[i]-lipgloss.Width(c)+2))
278			}
279		}
280		fmt.Fprintln(w)
281	}
282	
283	func styleName(sty authListStyles, name string) string {
284		if name == "" {
285			return sty.render(sty.dim, placeholderDash)
286		}
287		return sty.render(sty.name, name)
288	}
289	
290	func styleLastUsed(sty authListStyles, lastUsed *string, now time.Time) string {
291		if lastUsed == nil {
292			return sty.render(sty.dim, lastUsedNever)
293		}
294		return sty.render(sty.value, formatAuthLastUsed(lastUsed, now))
295	}
296	
297	func styleExpires(sty authListStyles, expiresAt string, now time.Time) string {
298		formatted := formatAuthDate(expiresAt)
299		switch classifyExpiresAt(expiresAt, now) {
300		case expiresExpired:
301			return sty.render(sty.expired, formatted)
302		case expiresSoon:
303			return sty.render(sty.warning, formatted)
304		case expiresNormal:
305			return sty.render(sty.value, formatted)
306		}
307		return sty.render(sty.value, formatted)
308	}
309	
310	func lastUsedSortKey(t api.Token) string {
311		if t.LastUsedAt == nil {
312			return ""
313		}
314		return *t.LastUsedAt
315	}
316	
317	// formatAuthDate renders an RFC3339 timestamp as YYYY-MM-DD in local time.
318	func formatAuthDate(s string) string {
319		if s == "" {
320			return placeholderDash
321		}
322		if ts, err := time.Parse(time.RFC3339, s); err == nil {
323			return ts.Local().Format("2006-01-02")
324		}
325		return s
326	}
327	
328	// formatAuthLastUsed renders a relative "last used" timestamp, with "yesterday"
329	// and absolute-date branches that the shared formatRelativeDuration helper
330	// doesn't cover.
331	func formatAuthLastUsed(s *string, now time.Time) string {
332		if s == nil || *s == "" {
333			return lastUsedNever
334		}
335		ts, err := time.Parse(time.RFC3339, *s)
336		if err != nil {
337			return *s
338		}
339		delta := now.Sub(ts)
340		switch {
341		case delta < 0, delta >= 30*24*time.Hour:
342			return ts.Local().Format("2006-01-02")
343		case delta >= 24*time.Hour && delta < 48*time.Hour:
344			return "yesterday"
345		default:
346			return formatRelativeDuration(delta)
347		}
348	}
349	
350	type expiresState int
351	
352	const (
353		expiresNormal expiresState = iota
354		expiresSoon
355		expiresExpired
356	)
357	
358	// classifyExpiresAt classifies an RFC3339 expires-at relative to now. Used to
359	// color the EXPIRES column so tokens worth rotating stand out.
360	func classifyExpiresAt(s string, now time.Time) expiresState {
361		if s == "" {
362			return expiresNormal
363		}
364		ts, err := time.Parse(time.RFC3339, s)
365		if err != nil {
366			return expiresNormal
367		}
368		delta := ts.Sub(now)
369		switch {
370		case delta <= 0:
371			return expiresExpired
372		case delta < 7*24*time.Hour:
373			return expiresSoon
374		default:
375			return expiresNormal
376		}
377	}
378	
379	func fallback(s, alt string) string {
380		if strings.TrimSpace(s) == "" {
381			return alt
382		}
383		return s
384	}
385	
386	// --- revoke -----------------------------------------------------------------
387	
388	func newAuthRevokeCmd() *cobra.Command {
389		var revokeCurrent bool
390		var insecureHTTPAuth bool
391		cmd := &cobra.Command{
392			Use:   "revoke [id]",
393			Short: "Revoke an API token by id",
394			Long:  "Revoke a specific API token. Use --current to revoke the token used by this CLI (equivalent to 'entire logout').",
395			Args:  cobra.MaximumNArgs(1),
396			RunE: func(cmd *cobra.Command, args []string) error {
397				id := ""
398				if len(args) == 1 {
399					id = args[0]
400				}
401				if id == "" && !revokeCurrent {
402					return cmd.Help()
403				}
404				if id != "" && revokeCurrent {
405					return errors.New("cannot use both <id> and --current")
406				}
407				if err := requireSecureBaseURL(insecureHTTPAuth); err != nil {
408					return err
409				}
410				return runAuthRevoke(cmd.Context(), cmd.OutOrStdout(), cmd.ErrOrStderr(),
411					auth.NewStore(), defaultListTokens, defaultRevokeTokenByID, defaultRevokeCurrentToken,
412					api.BaseURL(), id, revokeCurrent)
413			},
414		}
415		cmd.Flags().BoolVar(&revokeCurrent, "current", false, "Revoke the token used by this CLI and remove the local copy")
416		addInsecureHTTPAuthFlag(cmd, &insecureHTTPAuth)
417		return cmd
418	}
419	
420	func defaultRevokeTokenByID(ctx context.Context, callerToken, id string) error {
421		return api.NewClient(callerToken).RevokeToken(ctx, id) //nolint:wrapcheck // RevokeToken already wraps with action context
422	}
423	
424	func runAuthRevoke(
425		ctx context.Context,
426		outW, errW io.Writer,
427		store tokenStore,
428		list authTokenLister,
429		revokeByID authTokenRevoker,
430		revokeCurrent revokeCurrentFunc,
431		baseURL, id string,
432		current bool,
433	) error {
434		token, err := store.GetToken(baseURL)
435		if err != nil {
436			return fmt.Errorf("read keychain: %w", err)
437		}
438		if token == "" {
439			return fmt.Errorf("not logged in to %s; run 'entire login' first", baseURL)
440		}
441	
442		if current {
443			// Revoking our own token is just logout — reuse that path so behavior
444			// stays identical (best-effort revoke + local delete).
445			return runLogout(ctx, outW, errW, store, revokeCurrent, baseURL)
446		}
447	
448		if err := revokeByID(ctx, token, id); err != nil {
449			return err
450		}
451	
452		// The list endpoint requires bearer auth, so a 401 here means the id we
453		// just revoked was the same one this CLI is using — the keychain entry is
454		// now stale and would otherwise produce confusing 401s on every command.
455		if _, listErr := list(ctx, token); listErr != nil && api.IsHTTPErrorStatus(listErr, http.StatusUnauthorized) {
456			if delErr := store.DeleteToken(baseURL); delErr != nil {
457				return fmt.Errorf("revoked token %s but failed to remove local copy: %w", id, delErr)
458			}
459			fmt.Fprintf(outW, "Revoked token %s (this was your local token; removed from keychain).\n", id)
460			return nil
461		}
462	
463		fmt.Fprintf(outW, "Revoked token %s.\n", id)
464		return nil
465	}
