// searchTokenResourceURL strips any path/query/fragment from serviceURL so it
// passes tokenmanager.TokenRequest.Resource's origin-URL validation. Input
// like "https://api.example.com/search?foo=bar" reduces to
// "https://api.example.com". Falls through verbatim on parse failure or when
// the input isn't a URL — TokenForResource will surface the validation error.
func searchTokenResourceURL(serviceURL string) string {
	raw := strings.TrimSpace(serviceURL)
	u, err := url.Parse(raw)
	if err != nil || u.Scheme == "" || u.Host == "" {
		return raw
	}
	return (&url.URL{Scheme: u.Scheme, Host: u.Host}).String()
}

