96	func NormalizeWindow(since, until time.Time) (time.Time, time.Time) {
97		floored := since.Truncate(time.Minute)
98		ceiled := until.Truncate(time.Minute)
99		if !until.Equal(ceiled) {
100			ceiled = ceiled.Add(time.Minute)
101		}
102		return floored, ceiled
103	}
104	
105	func resolveRepoRoots(ctx context.Context, repoPaths []string) ([]string, error) {
106		if len(repoPaths) == 0 {
107			repoRoot, err := paths.WorktreeRoot(ctx)
108			if err != nil {
109				return nil, fmt.Errorf("not in a git repository: %w", err)
110			}
111			return []string{repoRoot}, nil
112		}
113	
114		roots := make([]string, 0, len(repoPaths))
115		for _, repoPath := range repoPaths {
116			cmd := exec.CommandContext(ctx, "git", "-C", repoPath, "rev-parse", "--show-toplevel")
117			output, err := cmd.Output()
118			if err != nil {
119				return nil, fmt.Errorf("resolve repo root for %q: %w", repoPath, err)
120			}
121			roots = append(roots, strings.TrimSpace(string(output)))
122		}
123		return roots, nil
124	}
125	
126	func enumerateRepoCandidates(ctx context.Context, repoRoot string, opts Options, since, until time.Time) ([]candidate, error) {
127		repo, err := git.PlainOpenWithOptions(repoRoot, &git.PlainOpenOptions{DetectDotGit: true})
128		if err != nil {
129			return nil, fmt.Errorf("open repository %s: %w", repoRoot, err)
130		}
131	
132		repoFullName, err := resolveRepoFullName(ctx, repo)
133		if err != nil {
134			return nil, fmt.Errorf("resolve repo name for %s: %w", repoRoot, err)
135		}
136	
137		branches := opts.Branches
138		switch {
139		case opts.AllBranches:
140			branches, err = localBranchNames(repo)
141			if err != nil {
142				return nil, err
143			}
144		case len(branches) == 0:
145			currentBranch, err := currentBranchName(repo)
146			if err != nil {
147				return nil, err
148			}
149			branches = []string{currentBranch}
150		}
151		branchSet := make(map[string]struct{}, len(branches))
152		for _, branch := range branches {
153			branchSet[branch] = struct{}{}
154		}
155		reachableCheckpointIDs := map[string]struct{}{}
156		if opts.ImplicitCurrentBranch && !opts.AllBranches {
157			reachableCheckpointIDs, err = reachableCheckpointIDsInRange(ctx, repoRoot, branchLocalRevRange(ctx, repoRoot), since)
158			if err != nil {
159				return nil, err
160			}
161		}
162		commitSubjectsByCheckpoint, err := loadCommitSubjectsByCheckpoint(ctx, repoRoot, since)
163		if err != nil {
164			return nil, err
165		}
166	
167		store := checkpoint.NewGitStore(repo)
168		infos, err := store.ListCommitted(ctx)
169		if err != nil {
170			return nil, fmt.Errorf("list committed checkpoints: %w", err)
171		}
172	
173		candidates := make([]candidate, 0, len(infos))
174		for _, info := range infos {
175			if info.CreatedAt.Before(since) || !info.CreatedAt.Before(until) {
176				continue
177			}
178	
179			summary, err := store.ReadCommitted(ctx, info.CheckpointID)
180			if err != nil {
181				logging.Warn(ctx, "failed to read committed checkpoint for dispatch", "checkpoint_id", info.CheckpointID.String(), "error", err)
182				continue
183			}
184			if summary == nil {
185				continue
186			}
187			if _, onSelectedBranch := branchSet[summary.Branch]; !onSelectedBranch {
188				if !opts.ImplicitCurrentBranch {
189					continue
190				}
191				if _, reachable := reachableCheckpointIDs[info.CheckpointID.String()]; !reachable {
192					continue
193				}
194			}
195	
196			localSummary := ""
197			if len(summary.Sessions) > 0 {
198				latestIndex := len(summary.Sessions) - 1
199				if metadata, err := store.ReadSessionMetadata(ctx, info.CheckpointID, latestIndex); err == nil && metadata != nil && metadata.Summary != nil {
200					localSummary = strings.TrimSpace(metadata.Summary.Outcome)
201					if localSummary == "" {
202						localSummary = strings.TrimSpace(metadata.Summary.Intent)
203					}
204				}
205			}
206	
207			commitSubject := commitSubjectsByCheckpoint[info.CheckpointID.String()]
208			candidates = append(candidates, candidate{
209				CheckpointID:      info.CheckpointID.String(),
210				RepoFullName:      repoFullName,
211				Branch:            summary.Branch,
212				CreatedAt:         info.CreatedAt,
213				CommitSubject:     commitSubject,
214				LocalSummaryTitle: localSummary,
215			})
216		}
217	
218		return candidates, nil
219	}
220	
221	func reachableCheckpointIDsInRange(ctx context.Context, repoRoot, revRange string, since time.Time) (map[string]struct{}, error) {
222		cmd := exec.CommandContext(
223			ctx,
224			"git",
225			"-C",
226			repoRoot,
227			"log",
228			revRange,
229			"--since="+since.UTC().Format(time.RFC3339),
230			"--grep",
231			"Entire-Checkpoint:",
232			"--format=%B%x00",
233		)
234		output, err := cmd.Output()
235		if err != nil {
236			return nil, fmt.Errorf("list HEAD checkpoint trailers: %w", err)
237		}
238	
239		reachable := make(map[string]struct{})
240		for _, message := range strings.Split(string(output), "\x00") {
241			for _, checkpointID := range trailers.ParseAllCheckpoints(message) {
242				reachable[checkpointID.String()] = struct{}{}
243			}
244		}
245		return reachable, nil
246	}
247	
248	// branchLocalRevRange returns a git log rev range that limits commits to
249	// those unique to the current branch — reachable from HEAD but not from the
250	// repository's default branch. Falls back to "HEAD" when no default branch
251	// can be resolved (e.g. a fresh repo with no main/master ref).
252	func branchLocalRevRange(ctx context.Context, repoRoot string) string {
253		base := defaultBranchRef(ctx, repoRoot)
254		if base == "" {
255			return "HEAD"
256		}
257		return base + "..HEAD"
258	}
259	
260	// defaultBranchRef resolves the repository's default branch, preferring
261	// origin/HEAD and falling back to the conventional main/master names. A
262	// candidate is only accepted if it is an ancestor of HEAD — otherwise a
263	// repo with an unconventional default (e.g. develop, trunk) would silently
264	// exclude the wrong history. Returns an empty string if nothing matches so
265	// callers can skip the exclusion.
266	func defaultBranchRef(ctx context.Context, repoRoot string) string {
267		if out, ok := runGitOutput(ctx, repoRoot, "symbolic-ref", "--quiet", "refs/remotes/origin/HEAD"); ok {
268			ref := strings.TrimSpace(out)
269			if strings.HasPrefix(ref, "refs/remotes/") {
270				candidate := strings.TrimPrefix(ref, "refs/remotes/")
271				if isAncestorOfHEAD(ctx, repoRoot, candidate) {
272					return candidate
273				}
274			}
275		}
276		for _, candidate := range []string{"origin/main", "origin/master", "main", "master"} {
277			if _, ok := runGitOutput(ctx, repoRoot, "rev-parse", "--verify", "--quiet", candidate); !ok {
278				continue
279			}
280			if isAncestorOfHEAD(ctx, repoRoot, candidate) {
281				return candidate
282			}
283		}
284		return ""
285	}
286	
287	func isAncestorOfHEAD(ctx context.Context, repoRoot, ref string) bool {
288		_, ok := runGitOutput(ctx, repoRoot, "merge-base", "--is-ancestor", ref, "HEAD")
289		return ok
290	}
291	
292	func runGitOutput(ctx context.Context, repoRoot string, args ...string) (string, bool) {
293		fullArgs := append([]string{"-C", repoRoot}, args...)
294		out, err := exec.CommandContext(ctx, "git", fullArgs...).Output()
295		if err != nil {
296			return "", false
297		}
298		return string(out), true
299	}
300	
301	func resolveRepoFullName(ctx context.Context, repo *git.Repository) (string, error) {
302		remote, err := repo.Remote("origin")
303		if err != nil {
304			logging.Warn(ctx, "dispatch repo resolution failed", "step", "origin_remote", "error", err)
305			return "", fmt.Errorf("dispatch currently supports GitHub repositories with an origin remote: %w", err)
306		}
307		if len(remote.Config().URLs) == 0 {
308			return "", errors.New("dispatch currently supports GitHub repositories with an origin remote URL")
309		}
310	
311		owner, repoName, err := search.ParseGitHubRemote(remote.Config().URLs[0])
312		if err != nil {
313			logging.Warn(ctx, "dispatch repo resolution failed", "step", "parse_origin_remote", "error", err)
314			return "", fmt.Errorf("dispatch currently supports GitHub origin remotes only: %w", err)
315		}
316		return owner + "/" + repoName, nil
317	}
318	
319	func currentBranchName(repo *git.Repository) (string, error) {
320		head, err := repo.Head()
321		if err != nil {
322			return "", fmt.Errorf("get HEAD: %w", err)
323		}
324		if !head.Name().IsBranch() {
325			return "", errors.New("not on a branch (detached HEAD)")
326		}
327		return head.Name().Short(), nil
328	}
329	
330	// localBranchNames returns the short names of the user's local branches,
331	// omitting the reserved "entire/" namespace used for internal refs.
332	func localBranchNames(repo *git.Repository) ([]string, error) {
333		iter, err := repo.Branches()
334		if err != nil {
335			return nil, fmt.Errorf("list local branches: %w", err)
336		}
337		defer iter.Close()
338	
339		var names []string
340		if err := iter.ForEach(func(ref *plumbing.Reference) error {
341			name := ref.Name().Short()
342			if strings.HasPrefix(name, checkpoint.ShadowBranchPrefix) {
343				return nil
344			}
345			names = append(names, name)
346			return nil
347		}); err != nil {
348			return nil, fmt.Errorf("iterate local branches: %w", err)
349		}
350		sort.Strings(names)
351		return names, nil
352	}
353	
354	func loadCommitSubjectsByCheckpoint(ctx context.Context, repoRoot string, since time.Time) (map[string]string, error) {
355		cmd := exec.CommandContext(
356			ctx,
357			"git",
358			"-C",
359			repoRoot,
360			"log",
361			"--all",
362			"--since="+since.UTC().Format(time.RFC3339),
363			"--grep",
364			"Entire-Checkpoint:",
365			"--format=%s%x00%B%x00%x00",
366		)
367		output, err := cmd.Output()
368		if err != nil {
369			return nil, fmt.Errorf("git log --grep: %w", err)
370		}
371	
372		subjects := make(map[string]string)
373		for _, record := range strings.Split(string(output), "\x00\x00") {
374			record = strings.TrimSuffix(record, "\x00")
375			if record == "" {
376				continue
377			}
378			parts := strings.SplitN(record, "\x00", 2)
379			if len(parts) != 2 {
380				continue
381			}
382			subject := strings.TrimSpace(parts[0])
383			for _, checkpointID := range trailers.ParseAllCheckpoints(parts[1]) {
384				id := checkpointID.String()
385				if _, ok := subjects[id]; ok {
386					continue
387				}
388				subjects[id] = subject
389			}
390		}
391		return subjects, nil
392	}
393	
394	func coveredRepos(candidates []candidate) []string {
395		if len(candidates) == 0 {
396			return nil
397		}
398	
399		repoSet := make(map[string]struct{}, len(candidates))
400		for _, candidate := range candidates {
401			if candidate.RepoFullName == "" {
402				continue
403			}
404			repoSet[candidate.RepoFullName] = struct{}{}
405		}
406	
407		repos := make([]string, 0, len(repoSet))
408		for repoFullName := range repoSet {
409			repos = append(repos, repoFullName)
410		}
411		sort.Strings(repos)
412		return repos
413	}
414	
415	func groupBulletsByRepo(used []repoBullet) []RepoGroup {
416		repoMap := make(map[string]map[string][]Bullet)
417		for _, item := range used {
418			if _, ok := repoMap[item.RepoFullName]; !ok {
419				repoMap[item.RepoFullName] = make(map[string][]Bullet)
420			}
421			label := "Updates"
422			if len(item.Bullet.Labels) > 0 && strings.TrimSpace(item.Bullet.Labels[0]) != "" {
423				label = item.Bullet.Labels[0]
424			}
425			repoMap[item.RepoFullName][label] = append(repoMap[item.RepoFullName][label], item.Bullet)
426		}
427	
428		repoNames := make([]string, 0, len(repoMap))
429		for repoName := range repoMap {
430			repoNames = append(repoNames, repoName)
431		}
432		sort.Strings(repoNames)
433	
434		out := make([]RepoGroup, 0, len(repoNames))
435		for _, repoName := range repoNames {
436			sectionMap := repoMap[repoName]
437			labels := make([]string, 0, len(sectionMap))
438			for label := range sectionMap {
439				labels = append(labels, label)
440			}
441			sort.Strings(labels)
442	
443			sections := make([]Section, 0, len(labels))
444			for _, label := range labels {
445				sections = append(sections, Section{
446					Label:   label,
447					Bullets: sectionMap[label],
448				})
449			}
450			out = append(out, RepoGroup{
451				FullName: repoName,
452				URL:      githubRepoURL(repoName),
453				Sections: sections,
454			})
455		}
456	
457		return out
458	}
459	
460	func firstAt(used []repoBullet) time.Time {
461		var first time.Time
462		for _, item := range used {
463			if item.Bullet.CreatedAt.IsZero() {
464				continue
465			}
466			if first.IsZero() || item.Bullet.CreatedAt.Before(first) {
467				first = item.Bullet.CreatedAt
468			}
469		}
470		return first
471	}
472	
473	func lastAt(used []repoBullet) time.Time {
474		var last time.Time
475		for _, item := range used {
476			if item.Bullet.CreatedAt.After(last) {
477				last = item.Bullet.CreatedAt
478			}
479		}
480		return last
481	}
